function make_stats(ovr, pos) {
  const base = Math.max(1, Math.min(20, Math.round(ovr * 0.2)));
  if (pos === 'GK') {
    return {
      finishing: 2, passing: Math.max(6, base - 5), dribbling: 3, firstTouch: Math.max(6, base - 5), technique: Math.max(6, base - 5),
      tackling: 4, marking: 4, heading: 5, longShots: 2, crossing: 2, freeKicks: 4,
      vision: Math.max(8, base - 4), decisions: Math.min(20, base), positioning: Math.min(20, base + 1), anticipation: Math.min(20, base),
      composure: Math.min(20, base), determination: Math.min(20, base), teamwork: 14, workRate: 14, offTheBall: 3, bravery: 16,
      pace: 10, acceleration: 11, stamina: 12, strength: 15, agility: Math.min(20, base + 1), jumping: Math.min(20, base + 1), balance: 14,
      reflexes: Math.min(20, base + 2), oneOnOnes: Math.min(20, base + 1), handling: Math.min(20, base + 1),
      aerial: Math.min(20, base + 1), kicking: Math.min(20, base), command: Math.min(20, base + 1)
    };
  } else if (['CB', 'LB', 'RB', 'LWB', 'RWB', 'DF'].includes(pos)) {
    const isFb = ['LB', 'RB', 'LWB', 'RWB'].includes(pos);
    return {
      finishing: isFb ? 7 : 5, passing: Math.min(20, base - (isFb ? 1 : 3)), dribbling: Math.min(20, base - (isFb ? 1 : 4)),
      firstTouch: Math.min(20, base - 2), technique: Math.min(20, base - 2),
      tackling: Math.min(20, base + 2), marking: Math.min(20, base + (isFb ? 1 : 2)), heading: Math.min(20, base + (isFb ? -1 : 2)),
      longShots: 8, crossing: Math.min(20, base + (isFb ? 1 : -5)), freeKicks: 7,
      vision: Math.min(20, base - 2), decisions: Math.min(20, base), positioning: Math.min(20, base + 2), anticipation: Math.min(20, base + 1),
      composure: Math.min(20, base), determination: 16, teamwork: 16, workRate: 16, offTheBall: isFb ? 13 : 7, bravery: 17,
      pace: Math.min(20, base + (isFb ? 2 : 0)), acceleration: Math.min(20, base + (isFb ? 2 : 0)), stamina: Math.min(20, base + 2),
      strength: Math.min(20, base + (isFb ? 0 : 2)), agility: Math.min(20, base + (isFb ? 1 : -1)), jumping: Math.min(20, base + (isFb ? -1 : 2)), balance: Math.min(20, base),
      reflexes: 2, oneOnOnes: 2, handling: 2, aerial: 2, kicking: 3, command: 2
    };
  } else if (['CDM', 'CM', 'CAM', 'RM', 'LM', 'MF'].includes(pos)) {
    const isCam = ['CAM', 'RM', 'LM'].includes(pos);
    return {
      finishing: Math.min(20, base + (isCam ? 0 : -2)), passing: Math.min(20, base + 2), dribbling: Math.min(20, base + (isCam ? 2 : 0)),
      firstTouch: Math.min(20, base + 2), technique: Math.min(20, base + 2),
      tackling: Math.min(20, base + (isCam ? -4 : 1)), marking: Math.min(20, base + (isCam ? -5 : 0)), heading: Math.min(20, base - 3),
      longShots: Math.min(20, base + 1), crossing: Math.min(20, base), freeKicks: Math.min(20, base),
      vision: Math.min(20, base + 2), decisions: Math.min(20, base + 2), positioning: Math.min(20, base + (isCam ? -1 : 1)), anticipation: Math.min(20, base + 1),
      composure: Math.min(20, base + 1), determination: 16, teamwork: 17, workRate: 17, offTheBall: Math.min(20, base + 1), bravery: 14,
      pace: Math.min(20, base + (isCam ? 1 : -1)), acceleration: Math.min(20, base + (isCam ? 1 : -1)), stamina: Math.min(20, base + 2),
      strength: Math.min(20, base - 1), agility: Math.min(20, base + 1), jumping: Math.min(20, base - 2), balance: Math.min(20, base + 1),
      reflexes: 2, oneOnOnes: 2, handling: 2, aerial: 2, kicking: 3, command: 2
    };
  } else {
    const isWinger = ['RW', 'LW'].includes(pos);
    return {
      finishing: Math.min(20, base + (isWinger ? 1 : 2)), passing: Math.min(20, base + (isWinger ? 0 : -2)), dribbling: Math.min(20, base + (isWinger ? 2 : 1)),
      firstTouch: Math.min(20, base + 1), technique: Math.min(20, base + 2),
      tackling: 5, marking: 4, heading: Math.min(20, base + (isWinger ? -3 : 1)),
      longShots: Math.min(20, base + 1), crossing: Math.min(20, base + (isWinger ? 2 : -3)), freeKicks: Math.min(20, base),
      vision: Math.min(20, base), decisions: Math.min(20, base), positioning: 8, anticipation: Math.min(20, base + 1),
      composure: Math.min(20, base + 1), determination: 16, teamwork: 14, workRate: 15, offTheBall: Math.min(20, base + 2), bravery: 14,
      pace: Math.min(20, base + (isWinger ? 2 : 1)), acceleration: Math.min(20, base + (isWinger ? 2 : 1)), stamina: Math.min(20, base),
      strength: Math.min(20, base + (isWinger ? -2 : 1)), agility: Math.min(20, base + (isWinger ? 2 : 0)), jumping: Math.min(20, base + (isWinger ? -2 : 1)), balance: Math.min(20, base + 1),
      reflexes: 2, oneOnOnes: 2, handling: 2, aerial: 2, kicking: 3, command: 2
    };
  }
}

if (typeof window !== 'undefined') {
  window.LEAGUES = LEAGUES;
  window.CLUBS = CLUBS;
  window.CLUB_MAP = CLUB_MAP;
  window.PLAYERS = PLAYERS;
  window.PLAYER_MAP = PLAYER_MAP;
  window.NEWGEN_NAME_POOLS = NEWGEN_NAME_POOLS;
  window.make_stats = make_stats;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { LEAGUES, CLUBS, CLUB_MAP, PLAYERS, PLAYER_MAP, NEWGEN_NAME_POOLS, make_stats };
}
